def log_emotion(self, emotion, intensity, user_name):
        try:
            import json as _json
            import tempfile as _tempfile
            log_path = os.path.join(
                os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__)))),
                'data', 'stream', 'hormone_emotion_log.json'
            )
            entry = {
                "timestamp": time.time(),
                "emotion": emotion,
                "intensity": round(intensity, 2),
                "user_name": user_name,
                "trend": self.get_emotion_trend().get("direction", "stable"),
            }
            with self._emotion_log_lock:
                log_data = []
                if os.path.exists(log_path):
                    try:
                        log_data = safe_read_json(log_path, default=[])
                    except Exception:
                        log_data = []
                log_data.append(entry)
                if len(log_data) > 50:
                    log_data = log_data[-50:]
                fd = None
                tmp_path = None
                try:
                    fd, tmp_path = _tempfile.mkstemp(
                        dir=os.path.dirname(log_path),
                        prefix='.hormone_emotion_log.',
                        suffix='.tmp'
                    )
                    with os.fdopen(fd, 'w', encoding='utf-8') as f:
                        _json.dump(log_data, f, ensure_ascii=False)
                        f.flush()
                        os.fsync(f.fileno())
                    os.replace(tmp_path, log_path)
                    tmp_path = None
                except Exception:
                    if fd is not None:
                        try:
                            os.close(fd)
                        except OSError:
                            pass
                    raise
                finally:
                    if tmp_path is not None:
                        try:
                            os.unlink(tmp_path)
                        except OSError:
                            pass
        except Exception as e:
            self._log(LogLevel.DEBUG, f"data processing exception ignored: {type(e).__name__}: {e}")
